from typing import List, Literal, TypedDict

class OrchestratorState(TypedDict):
    user_constraints: dict       # Immutable: {"region": "US", "tenant_id": "t_42"}
    artifacts: List[dict]        # Compact JSON outputs, never 20KB raw dumps
    next_agent: Literal["sql", "research", "done"]
    steps_used: int
    max_steps: int

def supervisor_router(state: OrchestratorState) -> str:
    if state["steps_used"] >= state["max_steps"]:
        return "done"  # Hard stop prevents infinite ping-pong loops
    return state["next_agent"]
